{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "The reported evidence for C01 explicitly identifies RGFP966, the query molecule, as brain-penetrant: subcutaneous dosing at 10 mg/kg in mice produced brain concentrations above the HDAC3 IC50 within 15 min, directly demonstrating meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "A high-transfer aryl enone/aniline-type radiotracer showed 5.47% ID/g brain uptake at 2 min in mice, supporting that this flat, aromatic, amide/enone-like chemotype can penetrate the BBB well.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "DAA1106, a lipophilic amide with logD 3.65 and high transfer relevance, showed rapid and high mouse brain uptake (2.1-3.5% ID/g), supporting that amide-containing lipophilic molecules of this class can achieve good brain exposure.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Direct in vivo evidence identifies the query as RGFP966, a brain-penetrant HDAC3 inhibitor, and multiple high-transfer analogues with similar amide/aromatic features also show good BBB uptake; therefore meaningful CNS access is predicted.",
  "evidence_gaps": [
    "No quantitative brain-to-plasma ratio or CSF concentration is provided for RGFP966, but brain concentration above the pharmacologically active IC50 is sufficient for meaningful access.",
    "Efflux liability was not directly measured for the query, but direct in vivo brain penetration evidence outweighs the uncertain transporter prior."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

